/* selectMasterMdAmUserManageList */ SELECT DISTINCT A.COM_CODE, A.COM_NAME_LOC, B.DEPARTMENT AS DEPT_CODE, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = B.COM_CODE AND TYPE='C001' AND CODE = B.DEPARTMENT) DEPT_NAME, /* 부서명 */ B.USER_NAME_LOC, F_GET_MASKING_RETURN(B.USER_NAME_LOC, 'NAME') AS USER_NAME_LOC_MASK, B.USER_ID, F_GET_MASKING_RETURN(B.USER_ID, 'NAME') AS USER_ID_MASK FROM ICOMCMPY A, ICOMLUSR B, KX_USERROLE C, KX_USERAUTH D WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND B.USER_ID = C.USER_ID(+) AND B.USER_ID = D.USER_ID(+) AND A.STATUS IN ('C', 'R') AND A.BUSINESS_COND = #{st_com_gubun} AND B.STATUS IN ('C','R')
AND A.COM_CODE = #{st_com_code}
AND B.DEPARTMENT = #{st_dept_code}
AND B.USER_ID = #{st_user_id}
AND B.USER_ID = #{st_user_id}
AND D.AUTH_ID = #{st_auth_info}
AND D.AUTH_ID IS NOT NULL
AND C.ROLE_ID = #{st_auth_info}
AND C.ROLE_ID IS NOT NULL

